const { data } = $input.first().json.body || $input.first().json;
const d = data?.diff || {};
const lines = [];
if (d.tables_added?.length) lines.push(`*Added tables:* ${d.tables_added.join(', ')}`);
if (d.tables_removed?.length) lines.push(`*Removed tables:* ${d.tables_removed.join(', ')}`);
if (d.columns_added?.length) lines.push(`*Added columns:* ${d.columns_added.map(c => `${c.table}.${c.column}`).join(', ')}`);
if (d.columns_removed?.length) lines.push(`*Removed columns:* ${d.columns_removed.map(c => `${c.table}.${c.column}`).join(', ')}`);
if (d.columns_changed?.length) lines.push(`*Changed columns:* ${d.columns_changed.map(c => `${c.table}.${c.column}`).join(', ')}`);
return [{ json: { text: `:warning: *Schema drift detected on DB ${data.database}*\n` + (lines.join('\n') || 'No diff?') } }];
